"use client";

import * as React from "react";
import { ChevronDown } from "lucide-react";

type DivProps = React.ComponentProps<"div">;
type DrawerState = "closed" | "opening" | "open" | "closing";
type Direction = "up" | "down";
type HighlightSource = "pointer" | "focus";

export type BreakdownTone = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5";

export type BreakdownSegment = {
  id: string;
  label: string;
  value: number;
  color?: BreakdownTone;
};

export type BreakdownFormat =
  | ((value: number) => string)
  | { style: "currency" | "number" | "percent"; currency?: string; maximumFractionDigits?: number };

export type BreakdownDelta = {
  /** Change in percent: 8.2 renders as +8.2%. */
  value: number;
  /** Context after the chip, e.g. "vs Sep". */
  label?: string;
  /** Which way is good. Costs and error rates want "down". Default "up". */
  goodDirection?: "up" | "down";
};

export type BreakdownStatCardProps = DivProps & {
  label: string;
  period?: string;
  value: number;
  format?: BreakdownFormat;
  delta?: BreakdownDelta;
  /** Parts of the value. Shares come from the sum of the segments, so they still add up to 100 when the segments do not cover the whole value. */
  segments: BreakdownSegment[];
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  /** Highlighted segment, for hosts that link the card to a chart. Leave undefined to let hover and focus drive it. */
  highlightedId?: string | null;
  onSegmentHover?: (id: string | null) => void;
  onSegmentSelect?: (id: string) => void;
  /** Drawer height morph, in ms. */
  expandDuration?: number;
  /** Roll of the segment amounts from 0 when the drawer opens, in ms. */
  rollDuration?: number;
};

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const EASE_IN = "cubic-bezier(0.4, 0, 1, 1)";
const TONES: BreakdownTone[] = ["chart-1", "chart-2", "chart-3", "chart-4", "chart-5"];
const BG: { [tone in BreakdownTone]: string } = {
  "chart-1": "bg-chart-1",
  "chart-2": "bg-chart-2",
  "chart-3": "bg-chart-3",
  "chart-4": "bg-chart-4",
  "chart-5": "bg-chart-5",
};
const DELTA_FORMAT = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1, signDisplay: "exceptZero" });

/** Whole-number shares that always add up to 100 (largest remainder method). */
export function breakdownShares(values: number[]): number[] {
  const positive = values.map((value) => Math.max(0, value));
  const total = positive.reduce((sum, value) => sum + value, 0);
  if (total <= 0) return positive.map(() => 0);
  const exact = positive.map((value) => (value / total) * 100);
  const shares = exact.map((share) => Math.floor(share));
  let left = 100 - shares.reduce((sum, share) => sum + share, 0);
  const order = exact.map((share, index) => ({ index, rest: share - Math.floor(share) })).sort((a, b) => b.rest - a.rest || a.index - b.index);
  for (const { index } of order) {
    if (left <= 0) break;
    shares[index] = (shares[index] ?? 0) + 1;
    left -= 1;
  }
  return shares;
}

function createFormatter(format: BreakdownFormat | undefined): (value: number) => string {
  if (typeof format === "function") return format;
  const style = format?.style ?? "number";
  const formatter = new Intl.NumberFormat("en-US", {
    style: style === "number" ? "decimal" : style,
    currency: style === "currency" ? (format?.currency ?? "USD") : undefined,
    minimumFractionDigits: 0,
    maximumFractionDigits: format?.maximumFractionDigits ?? 0,
  });
  return (value) => formatter.format(value);
}

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

type RollProps = {
  slot: string;
  text: string;
  direction: Direction;
  reduced: boolean;
  duration: number;
  /** Widest text this slot can show. Reserves that width so neighbours never shift while the text rolls. */
  sizer?: string;
  className?: string;
};

function Roll({ slot, text, direction, reduced, duration, sizer, className = "" }: RollProps) {
  const currentRef = React.useRef(null as HTMLSpanElement | null);
  const ghostRef = React.useRef(null as HTMLSpanElement | null);
  const previous = React.useRef(text);
  const [ghost, setGhost] = React.useState(null as { text: string; direction: Direction } | null);

  React.useLayoutEffect(() => {
    const from = previous.current;
    previous.current = text;
    const node = currentRef.current;
    if (from === text || reduced || !node || typeof node.animate !== "function") return;
    setGhost({ text: from, direction });
    node.animate(
      [{ transform: direction === "up" ? "translateY(100%)" : "translateY(-100%)", opacity: 0 }, { transform: "translateY(0)", opacity: 1 }],
      { duration, easing: EASE },
    );
  }, [text]);

  React.useLayoutEffect(() => {
    const node = ghostRef.current;
    if (!ghost || !node || typeof node.animate !== "function") {
      if (ghost) setGhost(null);
      return;
    }
    const out = node.animate(
      [{ transform: "translateY(0)", opacity: 1 }, { transform: ghost.direction === "up" ? "translateY(-100%)" : "translateY(100%)", opacity: 0 }],
      { duration, easing: EASE, fill: "forwards" },
    );
    out.onfinish = () => setGhost(null);
    return () => out.cancel();
  }, [ghost]);

  const reserved = sizer !== undefined;
  return (
    <span data-roll={slot} data-rolling={ghost ? "true" : "false"} className={`relative inline-block overflow-hidden whitespace-nowrap align-bottom ${className}`}>
      {reserved && <span aria-hidden="true" className="invisible block">{sizer}</span>}
      <span ref={currentRef} data-roll-current className={reserved ? "absolute inset-0 block" : "block"}>{text}</span>
      {ghost && <span ref={ghostRef} data-roll-ghost aria-hidden="true" className="absolute inset-0 block">{ghost.text}</span>}
    </span>
  );
}

function DeltaChip({ delta }: { delta: BreakdownDelta }) {
  const good = delta.value === 0 ? null : (delta.goodDirection ?? "up") === "up" ? delta.value > 0 : delta.value < 0;
  const tone = good === null ? "bg-muted text-muted-foreground" : good ? "bg-chart-2/15 text-foreground" : "bg-destructive/15 text-foreground";
  return (
    <span className="inline-flex items-baseline gap-1.5 text-xs">
      <span data-delta data-trend={good === null ? "flat" : good ? "good" : "bad"} className={`inline-flex items-center rounded-full px-2 py-0.5 font-medium tabular-nums ${tone}`}>
        {DELTA_FORMAT.format(delta.value)}%
      </span>
      {delta.label && <span data-delta-label className="text-muted-foreground">{delta.label}</span>}
    </span>
  );
}

export function BreakdownStatCard({
  label,
  period,
  value,
  format,
  delta,
  segments,
  expanded,
  defaultExpanded = false,
  onExpandedChange,
  highlightedId,
  onSegmentHover,
  onSegmentSelect,
  expandDuration = 240,
  rollDuration = 600,
  className = "",
  onKeyDown,
  ref,
  ...rest
}: BreakdownStatCardProps) {
  const reduced = useReducedMotion();
  const baseId = React.useId();
  const drawerId = `${baseId}-breakdown`;
  const controlled = expanded !== undefined;
  const [localExpanded, setLocalExpanded] = React.useState(defaultExpanded);
  const isExpanded = expanded ?? localExpanded;
  const [state, setState] = React.useState((isExpanded ? "open" : "closed") as DrawerState);
  const [localHighlight, setLocalHighlight] = React.useState(null as string | null);
  const [announce, setAnnounce] = React.useState("");
  const [progress, setProgress] = React.useState(1);

  const drawerRef = React.useRef(null as HTMLDivElement | null);
  const innerRef = React.useRef(null as HTMLDivElement | null);
  const toggleRef = React.useRef(null as HTMLButtonElement | null);
  const barRefs = React.useRef([] as (HTMLSpanElement | null)[]);
  const rowRefs = React.useRef([] as (HTMLLIElement | null)[]);
  const itemRefs = React.useRef([] as (HTMLButtonElement | null)[]);
  const previousExpanded = React.useRef(isExpanded);
  const heightAnimation = React.useRef(null as Animation | null);
  const frameRef = React.useRef(0);

  const fmt = React.useMemo(() => createFormatter(format), [format]);
  const shares = breakdownShares(segments.map((segment) => segment.value));
  const total = segments.reduce((sum, segment) => sum + Math.max(0, segment.value), 0);
  const highlightId = isExpanded ? (highlightedId !== undefined ? highlightedId : localHighlight) : null;
  const highlighted = highlightId ? (segments.find((segment) => segment.id === highlightId) ?? null) : null;
  const shownValue = highlighted ? highlighted.value : value;
  const sizer = [value, ...segments.map((segment) => segment.value)].map(fmt).reduce((widest, text) => (text.length > widest.length ? text : widest), "");
  const tabbable = Math.max(0, segments.findIndex((segment) => segment.id === highlightId));

  const setExpanded = (next: boolean) => {
    if (next === isExpanded) return;
    if (!controlled) setLocalExpanded(next);
    onExpandedChange?.(next);
  };

  const emitHighlight = (id: string | null, source: HighlightSource) => {
    setLocalHighlight(id);
    onSegmentHover?.(id);
    if (source !== "focus") return;
    const index = id ? segments.findIndex((segment) => segment.id === id) : -1;
    const segment = index >= 0 ? segments[index] : undefined;
    setAnnounce(segment ? `${segment.label}: ${fmt(segment.value)}, ${shares[index] ?? 0}% of ${label}` : "");
  };

  const leaveToFocused = () => {
    const focusedIndex = itemRefs.current.findIndex((node) => node !== null && node === document.activeElement);
    const focusedSegment = focusedIndex >= 0 ? segments[focusedIndex] : undefined;
    emitHighlight(focusedSegment ? focusedSegment.id : null, "pointer");
  };

  React.useLayoutEffect(() => {
    const drawer = drawerRef.current;
    const inner = innerRef.current;
    const was = previousExpanded.current;
    previousExpanded.current = isExpanded;
    if (!drawer || !inner) return;
    if (was === isExpanded) {
      if (drawer.style.height === "") drawer.style.height = isExpanded ? "auto" : "0px";
      return;
    }
    const bars = barRefs.current.filter((node): node is HTMLSpanElement => node !== null);
    const rows = rowRefs.current.filter((node): node is HTMLLIElement => node !== null);
    const from = drawer.getBoundingClientRect().height;
    heightAnimation.current?.cancel();
    heightAnimation.current = null;
    cancelAnimationFrame(frameRef.current);
    frameRef.current = 0;
    if (!isExpanded && localHighlight !== null) {
      setLocalHighlight(null);
      onSegmentHover?.(null);
    }
    if (!isExpanded) setAnnounce("");
    const animated = !reduced && typeof drawer.animate === "function";
    const target = isExpanded ? inner.offsetHeight : 0;
    if (!animated) {
      for (const bar of bars) for (const animation of bar.getAnimations()) animation.cancel();
      drawer.style.height = isExpanded ? "auto" : "0px";
      setState(isExpanded ? "open" : "closed");
      setProgress(1);
      return;
    }
    setState(isExpanded ? "opening" : "closing");
    drawer.style.height = `${target}px`;
    const animation = drawer.animate([{ height: `${from}px` }, { height: `${target}px` }], { duration: expandDuration, easing: EASE });
    heightAnimation.current = animation;
    animation.onfinish = () => {
      heightAnimation.current = null;
      drawer.style.height = isExpanded ? "auto" : "0px";
      setState(isExpanded ? "open" : "closed");
    };
    if (isExpanded) {
      bars.forEach((bar, index) => {
        for (const running of bar.getAnimations()) running.cancel();
        bar.animate([{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }], { duration: 320, delay: index * 60, easing: EASE, fill: "backwards" });
      });
      rows.forEach((row, index) => {
        for (const running of row.getAnimations()) running.cancel();
        row.animate([{ opacity: 0, transform: "translateY(6px)" }, { opacity: 1, transform: "translateY(0)" }], { duration: 300, delay: 60 + index * 50, easing: EASE, fill: "backwards" });
      });
      setProgress(0);
      const started = performance.now();
      const tick = (now: number) => {
        const t = Math.min(1, (now - started) / Math.max(1, rollDuration));
        setProgress(1 - (1 - t) ** 3);
        frameRef.current = t < 1 ? requestAnimationFrame(tick) : 0;
      };
      frameRef.current = requestAnimationFrame(tick);
    } else {
      const count = bars.length;
      bars.forEach((bar, index) => {
        for (const running of bar.getAnimations()) running.cancel();
        bar.animate([{ transform: "scaleX(1)" }, { transform: "scaleX(0)" }], { duration: 200, delay: (count - 1 - index) * 40, easing: EASE_IN, fill: "forwards" });
      });
      setProgress(1);
    }
  }, [isExpanded]);

  React.useEffect(() => () => {
    heightAnimation.current?.cancel();
    cancelAnimationFrame(frameRef.current);
  }, []);

  const onRootKeyDown: DivProps["onKeyDown"] = (event) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    if (event.key === "Escape" && isExpanded) {
      event.preventDefault();
      setExpanded(false);
      toggleRef.current?.focus();
    }
  };

  const onLegendKeyDown = (event: React.KeyboardEvent) => {
    const count = segments.length;
    if (!count) return;
    const current = Math.max(0, itemRefs.current.findIndex((node) => node !== null && node === event.target));
    let next = -1;
    if (event.key === "ArrowRight" || event.key === "ArrowDown") next = (current + 1) % count;
    else if (event.key === "ArrowLeft" || event.key === "ArrowUp") next = (current - 1 + count) % count;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = count - 1;
    if (next < 0) return;
    event.preventDefault();
    itemRefs.current[next]?.focus();
  };

  const mark = (id: string) => (highlighted ? (highlighted.id === id ? "true" : "other") : "false");
  const closed = state === "closed";

  return (
    <div
      ref={ref}
      {...rest}
      data-slot="breakdown-stat-card"
      data-state={state}
      data-expanded={isExpanded ? "true" : "false"}
      data-highlighted={highlighted?.id ?? ""}
      data-rolling={progress < 1 ? "true" : "false"}
      onKeyDown={onRootKeyDown}
      className={`relative rounded-2xl bg-card p-5 text-card-foreground shadow-sm ring-1 ring-border ${className}`}
    >
      <button
        ref={toggleRef}
        type="button"
        data-toggle
        aria-expanded={isExpanded}
        aria-controls={drawerId}
        onClick={() => setExpanded(!isExpanded)}
        className="group flex w-full cursor-pointer items-start justify-between gap-3 rounded-md text-left outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card"
      >
        <span className="flex min-w-0 items-baseline gap-1.5 text-sm">
          <Roll
            slot="label"
            text={highlighted ? highlighted.label : label}
            direction={highlighted ? "up" : "down"}
            reduced={reduced}
            duration={320}
            className={`font-medium transition-colors duration-200 motion-reduce:transition-none ${highlighted ? "text-foreground" : "text-muted-foreground"}`}
          />
          {period && <span data-period className="truncate text-muted-foreground/80">· {period}</span>}
        </span>
        <span aria-hidden="true" className="-mr-1.5 -mt-1.5 flex size-7 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors duration-200 group-hover:bg-muted group-hover:text-foreground motion-reduce:transition-none">
          <ChevronDown className={`size-4 transition-transform duration-300 ease-out motion-reduce:transition-none ${isExpanded ? "rotate-180" : ""}`} />
        </span>
      </button>

      <div className="mt-2 flex flex-wrap items-baseline gap-x-3 gap-y-1">
        <Roll
          slot="value"
          text={fmt(shownValue)}
          sizer={sizer}
          direction={highlighted ? "up" : "down"}
          reduced={reduced}
          duration={420}
          className="text-4xl font-semibold leading-[1.2] tracking-tight tabular-nums"
        />
        {delta && <DeltaChip delta={delta} />}
      </div>

      <div
        ref={drawerRef}
        id={drawerId}
        data-drawer
        data-state={state}
        role="region"
        aria-label={`Breakdown of ${label}`}
        aria-hidden={closed}
        inert={closed}
        className="overflow-hidden data-[state=closed]:invisible data-[state=closed]:h-0"
      >
        <div ref={innerRef} data-drawer-inner className="pt-4">
          <div data-bar aria-hidden="true" onPointerLeave={leaveToFocused} className="flex h-2.5 gap-0.5">
            {segments.map((segment, index) => (
              <span
                key={segment.id}
                ref={(node) => { barRefs.current[index] = node; }}
                data-segment-bar={segment.id}
                data-highlight={mark(segment.id)}
                onPointerEnter={() => emitHighlight(segment.id, "pointer")}
                onClick={() => onSegmentSelect?.(segment.id)}
                style={{ flexGrow: total > 0 ? Math.max(0, segment.value) / total : 0, flexBasis: 0, minWidth: segment.value > 0 ? 3 : 0 }}
                className={`h-full origin-left cursor-pointer rounded-full transition-[translate,opacity,filter] duration-200 ease-out motion-reduce:transition-none data-[highlight=other]:opacity-[0.55] data-[highlight=true]:-translate-y-0.5 data-[highlight=true]:brightness-110 ${BG[segment.color ?? TONES[index % TONES.length] ?? "chart-1"]}`}
              />
            ))}
          </div>
          <ul
            data-legend
            role="list"
            aria-label={`${label} by segment`}
            onKeyDown={onLegendKeyDown}
            onPointerLeave={leaveToFocused}
            onBlur={(event) => { if (!(event.relatedTarget instanceof Node && event.currentTarget.contains(event.relatedTarget))) emitHighlight(null, "focus"); }}
            className="-mx-2 mt-3 space-y-px"
          >
            {segments.map((segment, index) => (
              <li key={segment.id} ref={(node) => { rowRefs.current[index] = node; }} role="listitem">
                <button
                  ref={(node) => { itemRefs.current[index] = node; }}
                  type="button"
                  data-segment={segment.id}
                  data-highlight={mark(segment.id)}
                  data-percent={shares[index] ?? 0}
                  tabIndex={index === tabbable ? 0 : -1}
                  onPointerEnter={() => emitHighlight(segment.id, "pointer")}
                  onFocus={() => emitHighlight(segment.id, "focus")}
                  onClick={() => onSegmentSelect?.(segment.id)}
                  className="group flex w-full cursor-pointer items-center gap-2.5 rounded-lg px-2 py-1.5 text-left text-sm outline-none transition-[opacity,background-color] duration-200 hover:bg-muted/70 focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transition-none data-[highlight=other]:opacity-[0.55] data-[highlight=true]:bg-muted/70"
                >
                  <span aria-hidden="true" className={`size-2 shrink-0 rounded-full transition-transform duration-200 group-data-[highlight=true]:scale-125 motion-reduce:transition-none ${BG[segment.color ?? TONES[index % TONES.length] ?? "chart-1"]}`} />
                  <span data-name className="min-w-0 flex-1 truncate font-medium">{segment.label}</span>
                  <span data-share className="w-10 shrink-0 text-right tabular-nums text-muted-foreground">{shares[index] ?? 0}%</span>
                  <span data-amount className="w-24 shrink-0 text-right tabular-nums">{fmt(segment.value * progress)}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      </div>
      <p role="status" aria-live="polite" className="sr-only">{announce}</p>
    </div>
  );
}

export default BreakdownStatCard;

